-- =============================================================================
-- 20260101001300_replace_locations_from_kato.sql
-- Замена справочника локаций на КАТО 18.06.2026
-- Regions: 20, cities: 10120, districts: 19
-- Remap listings/events по slug региона + нормализованному имени
-- =============================================================================

begin;

-- 1. kato_code
alter table public.regions add column if not exists kato_code text;
alter table public.cities add column if not exists kato_code text;
alter table public.districts add column if not exists kato_code text;

create unique index if not exists regions_kato_code_uidx on public.regions (kato_code) where kato_code is not null;
create unique index if not exists cities_kato_code_uidx on public.cities (kato_code) where kato_code is not null;
create unique index if not exists districts_kato_code_uidx on public.districts (kato_code) where kato_code is not null;

-- 2. Staging
create temporary table regions_new (
  id smallint primary key,
  slug text not null,
  name_ru text not null,
  name_kk text not null,
  kato_code text not null
) on commit drop;

create temporary table cities_new (
  id integer primary key,
  region_id smallint not null,
  slug text not null,
  name_ru text not null,
  name_kk text not null,
  kato_code text not null,
  match_key text not null,
  is_city smallint not null default 0
) on commit drop;

create temporary table districts_new (
  id integer primary key,
  city_id integer not null,
  slug text not null,
  name_ru text not null,
  name_kk text not null,
  kato_code text not null,
  match_key text not null
) on commit drop;

