-- 6. Normalize helpers (immutable expressions via temp functions)
create or replace function pg_temp.norm_name(t text)
returns text language sql immutable as $$
  select regexp_replace(
    translate(lower(coalesce(t, '')), 'ёәғқңөұүһі', 'еагкноуухи'),
    '[^a-zа-я0-9]+', '', 'g'
  );
$$;

create or replace function pg_temp.norm_district(t text)
returns text language sql immutable as $$
  select pg_temp.norm_name(
    regexp_replace(
      regexp_replace(coalesce(t, ''), '^район\s+', '', 'i'),
      '(ский|ный|овый|ий|ый)$', '', 'i'
    )
  );
$$;

-- 7. ID maps (old → new)
create temporary table region_id_map (
  old_id smallint primary key,
  new_id smallint not null
) on commit drop;

insert into region_id_map (old_id, new_id)
select r.id, n.id
from public.regions r
join regions_new n on n.slug = r.slug;

create temporary table city_id_map (
  old_id integer primary key,
  new_id integer not null
) on commit drop;

insert into city_id_map (old_id, new_id)
select distinct on (c.id) c.id, n.id
from public.cities c
join public.regions r on r.id = c.region_id
join region_id_map rm on rm.old_id = r.id
join cities_new n
  on n.region_id = rm.new_id
 and n.match_key = pg_temp.norm_name(c.name_ru)
order by c.id, n.is_city desc, n.kato_code;

create temporary table district_id_map (
  old_id integer primary key,
  new_id integer not null
) on commit drop;

insert into district_id_map (old_id, new_id)
select distinct on (d.id) d.id, n.id
from public.districts d
join public.cities c on c.id = d.city_id
join city_id_map cm on cm.old_id = c.id
join districts_new n
  on n.city_id = cm.new_id
 and n.match_key = pg_temp.norm_district(d.name_ru)
order by d.id, n.kato_code;

-- 8. Snapshot listing/event remaps before DELETE (SET NULL)
create temporary table listing_remap (
  listing_id uuid primary key,
  region_id smallint,
  city_id integer,
  district_id integer
) on commit drop;

insert into listing_remap (listing_id, region_id, city_id, district_id)
select
  l.id,
  rm.new_id,
  cm.new_id,
  dm.new_id
from public.listings l
left join region_id_map rm on rm.old_id = l.region_id
left join city_id_map cm on cm.old_id = l.city_id
left join district_id_map dm on dm.old_id = l.district_id
where l.region_id is not null or l.city_id is not null or l.district_id is not null;

create temporary table event_remap (
  event_id uuid primary key,
  city_id integer
) on commit drop;

insert into event_remap (event_id, city_id)
select e.id, cm.new_id
from public.events e
left join city_id_map cm on cm.old_id = e.city_id
where e.city_id is not null;

-- 9. Replace dictionary
delete from public.districts;
delete from public.cities;
delete from public.regions;

insert into public.regions (id, slug, name_ru, name_kk, kato_code)
select id, slug, name_ru, name_kk, kato_code from regions_new;

insert into public.cities (id, region_id, slug, name_ru, name_kk, kato_code)
select id, region_id, slug, name_ru, name_kk, kato_code from cities_new;

insert into public.districts (id, city_id, slug, name_ru, name_kk, kato_code)
select id, city_id, slug, name_ru, name_kk, kato_code from districts_new;

-- 10. Restore FKs on content
update public.listings l
set
  region_id = lr.region_id,
  city_id = lr.city_id,
  district_id = lr.district_id
from listing_remap lr
where l.id = lr.listing_id;

update public.events e
set city_id = er.city_id
from event_remap er
where e.id = er.event_id;

-- 11. Sequences
select setval(pg_get_serial_sequence('public.regions', 'id'), coalesce((select max(id) from public.regions), 1));
select setval(pg_get_serial_sequence('public.cities', 'id'), coalesce((select max(id) from public.cities), 1));
select setval(pg_get_serial_sequence('public.districts', 'id'), coalesce((select max(id) from public.districts), 1));

commit;